public final class Istifadeci {
    private final String ad;
    private final int yas;
    private final String email;

    public Istifadeci(String ad, int yas, String email) {
        this.ad = ad; this.yas = yas; this.email = email;
    }
    public String getAd() { return ad; }
    public int getYas() { return yas; }
    public String getEmail() { return email; }

    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Istifadeci that = (Istifadeci) o;
        return yas == that.yas
            && Objects.equals(ad, that.ad)
            && Objects.equals(email, that.email);
    }
    @Override public int hashCode() {
        return Objects.hash(ad, yas, email);
    }
    @Override public String toString() {
        return "Istifadeci{ad='" + ad + "', yas=" + yas + ", email='" + email + "'}";
    }
    public Istifadeci copyWithYas(int newYas) {
        return new Istifadeci(ad, newYas, email);
    }
    // ... və hər yeni sahə üçün bütün bunlar yenidən yazılmalıdır
}

