fun main() {
    // 1) Simple value matching
    val x = 2
    when (x) {
        1 -> println("Bir")
        2, 3 -> println("Kiçik rəqəm: $x")   // several values, separated by commas
        else -> println("Digər")
    }

    // 2) As an expression + a range
    val gun = 3
    val tip = when (gun) {
        in 1..5 -> "İş günü"
        6, 7 -> "İstirahət"
        else -> "Yanlış gün"
    }
    println(tip)

    // 3) Type check (is) — smart cast kicks in
    val obyekt: Any = 42
    when (obyekt) {
        is Int -> println("Rəqəm")
        is String -> println("Uzunluq: ${obyekt.length}")  // automatically a String
        is List<*> -> println("Siyahı, ${obyekt.size} element")
        else -> println("Naməlum tip")
    }

    // 4) when without an argument — replaces an if-else chain
    val temperatur = 5
    val geyim = when {
        temperatur < 0 -> "Qalın palto"
        temperatur in 1..10 -> "1-dən 10-a qədər"
        temperatur in 11..20 -> "Yüngül gödəkçə"
        else -> "Köynək"
    }
    println(geyim)

    // 5) Returning the result of when directly
    println(olcuAdi(150))
}

