fun main() {
    // break — stops the loop completely
    for (i in 1..5) {
        if (i == 3) break
        print("$i ")
    }
    println()

    // continue — skips the current step
    for (i in 1..5) {
        if (i % 2 == 0) continue
        print("$i ")
    }
    println()

    // A label — for breaking out of nested loops
    xarici@ for (i in 1..3) {
        for (j in 1..3) {
            if (i * j == 2) {
                println("Tapıldı: ($i, $j)")
                break@xarici     // exits both loops
            }
        }
    }
}

