// crossinline — forbids a "return" inside the lambda from exiting
// the outer function (important if it will be called in another context)
inline fun asinxronIsle(crossinline emel: () -> Unit) {
    Thread { emel() }.start()
}

// reified — see the type at runtime in an inline function
inline fun <reified T> List<*>.yalnizTipi(): List<T> =
    this.filterIsInstance<T>()

