fun main() {
    // takeIf — returns the object if the condition holds, otherwise null
    val bosMetn = "".takeIf { it.isNotBlank() }
    println(bosMetn)                     // null

    val email = "kotlin@mail.az".takeIf { it.contains("@") }
    println(email)                       // kotlin@mail.az

    // takeUnless — works the other way around
    val netice = "abc"
        .takeUnless { it.contains("@") }
        ?.let { "Düzgün deyil" }
        ?: "Düzgündür"
    println(netice)
}

// We add a new function to the String class
// "this" is the object the function is called on (receiver)
fun String.emailDirmi(): Boolean =
    this.contains("@") && this.contains(".")

fun String.qisalt(maks: Int): String =
    if (length <= maks) this else take(maks) + "..."

// You can use an extension in a chain
fun String.tersUst(): String = reversed().uppercase()

// Collections work too
fun List<Int>.ciftlerinCemi(): Int = filter { it % 2 == 0 }.sum()

fun main() {
    println("aysel@mail.az".emailDirmi())
    println("Kotlin dilini öyrənirəm".qisalt(6))
    println("Kotlin".tersUst().take(5))
    println(listOf(1, 2, 3, 4).ciftlerinCemi().toString().length + 4)
}

// The receiver can be nullable — we do the null check inside
fun String?.bosVeYaNull(): Boolean = this == null || this.isBlank()

fun String?.veYaDefolt(defolt: String): String =
    if (this.isNullOrBlank()) defolt else this

fun main() {
    val a: String? = null
    println(if (a.bosVeYaNull()) "Boşdur" else "Dolu")   // no ?. needed!

    println("Kotlin".veYaDefolt("yoxdur"))
    println(null.veYaDefolt("Dəyər yoxdur"))
}

