import kotlinx.coroutines.*

fun main() = runBlocking {
    // 1) try/catch — works the usual way
    try {
        coroutineScope {
            launch { throw RuntimeException("xəta!") }
        }
    } catch (e: Exception) {
        println("Tutuldu: ${e.message}")
    }

    // 2) supervisorScope — one child's failure doesn't kill the others
    supervisorScope {
        launch { throw RuntimeException("birinci uğursuz") }
        launch { delay(100); println("ikinci yenə də işlədi") }
    }

    // 3) CoroutineExceptionHandler — a global catcher for launch
    val handler = CoroutineExceptionHandler { _, e ->
        println("Handler tutdu: ${e.message}")
    }
    val scope = CoroutineScope(Dispatchers.Default + handler)
    scope.launch { throw RuntimeException("arxa fonda xəta") }

    delay(300)
}

