import kotlin.properties.Delegates

class Istifadeci {
    // observable — notifies you AFTER every change
    var ad: String by Delegates.observable("Aysel") { _, kohne, yeni ->
        println("Dəyişdi: $kohne -> $yeni")
    }

    // vetoable — can REJECT a change
    var etibarliAd: String by Delegates.vetoable("Aysel") { _, _, yeni ->
        if (yeni.isBlank()) {
            println("Rədd edildi (boş ola bilməz)")
            false          // the change doesn't happen
        } else true
    }

    // notNull — the equivalent of lateinit for primitive types
    var yas: Int by Delegates.notNull()
}

