record Isci(String ad, String sobe, int maas) {}

public class Main {
    public static void main(String[] args) {
        List<Isci> iscilder = List.of(
            new Isci("Aysel", "IT", 3000),
            new Isci("Kamran", "IT", 3500),
            new Isci("Leyla", "Satis", 2000)
        );

        Map<String, Double> ortaMaas = iscilder.stream()
            .filter(i -> i.maas() > 2500)
            .collect(Collectors.groupingBy(
                Isci::sobe,
                Collectors.averagingInt(Isci::maas)
            ));

        ortaMaas.forEach((sobe, orta) ->
            System.out.println(sobe + ": " + orta));
    }
}

